component_declaration.syntax:
component MetricCard(title = "Total Users", value = "12,450", trend = "+8.2%") {
    size: 240px 140px;
    background: #19271D;
    radius: 14px;
    stroke: alpha(#87CC2E, 0.2) 1px;

    text #lblTitle {
        at: (20px, 20px);
        content: title;
        font-size: 13px;
        color: #9EB0A3;
    }

    text #lblValue {
        at: (20px, 48px);
        content: value;
        font-size: 28px;
        font-weight: 700;
        color: #ffffff;
    }

    text #lblTrend {
        at: (20px, 94px);
        content: trend;
        font-size: 12px;
        font-weight: 600;
        color: #87CC2E;
    }
}

instantiation.example:
// Positional
MetricCard #users("Monthly Active", "45,200", "+14.3%") {
    at: (40px, 40px);
}

// Named override
MetricCard #revenue(value = "$98,400", title = "MRR") {
    at: right of #users offset 24px;
}
